// === Tab: mySketch ===
let particles = []; //array of particles

function setup() {
  createCanvas(windowWidth, windowHeight);
  background(200, 120, 30, 20);

  // Automatically generate a particle every 2 seconds (2000ms)
  setInterval(() => {
    let x = random(width); // random x position
    let y = random(height); // random y position
    let mag = random(1, 20); // random magnitude for rate
    particles.push(new Particle(x, y, map(mag, 0, 20, 0.1, 1)));
  }, 2000);
}

function draw() {
  for (let i = particles.length - 1; i >= 0; i--) {
    particles[i].update();
    particles[i].show();
    if (particles[i].alpha <= 2) particles.splice(i, 1); // remove the dead particle
  }
}

// Particle class
class Particle {
  constructor(x, y, r) {
    this.location = createVector(x, y);
    this.velocity = createVector(random(-1, 1), random(-1, 1));
    this.alpha = 45;
    this.amp = 20;
    this.rate = r;
  }

  update() {
    this.location.add(this.velocity);
    this.alpha -= this.rate;
    this.amp -= this.rate;
  }

  show() {
    noStroke();
    fill(0, 35, 25, this.alpha);
    ellipse(this.location.x, this.location.y, this.amp);
  }
}

